const text = $input.first().json.text;

// Title (# ke baad wali line)
const subject = $input.first().json.subject || "";
let title = subject.replace(/^New Job:\s*/i, "").replace(/^#\s*/, "").trim();
if (!title) title = "Unknown";

// Budget (Hourly ya Fixed, jo bhi ho)
const rateMatch = text.match(/Hourly Rate: (.+)/);
const fixedMatch = text.match(/Fixed[- ]?[Pp]rice: (.+)/);
const budget = rateMatch ? `Hourly: ${rateMatch[1].trim()}` 
             : fixedMatch ? `Fixed: ${fixedMatch[1].trim()}` 
             : "Unknown";

// Description (Filter line ke baad se, Client rank se pehle tak)
const descMatch = text.match(/Filter:[\s\S]*?\]\s*\n\n([\s\S]*?)\n\nClient rank:/);
const description = descMatch ? descMatch[1].replace(/\s+/g, ' ').trim() : "Unknown";

// Client Info
const clientRankMatch = text.match(/Client rank: (\w+)/);
const clientRank = clientRankMatch ? clientRankMatch[1] : "Unknown";

const paymentVerified = text.includes("Payment method verified");

const reviewsMatch = text.match(/(no reviews|[\d.]+ of \d+ reviews)/);
const reviews = reviewsMatch ? reviewsMatch[1] : "Unknown";

const registeredMatch = text.match(/Registered: (.+)/);
const registered = registeredMatch ? registeredMatch[1].trim() : "Unknown";

// Job URL (Upwork wala asal link, tracking link ke andar se decode karke)
const urlBlockMatch = text.match(/View on Upwork[\s\S]*?\[(https:\/\/[^\]]+)\]/);
let jobUrl = "Unknown";
if (urlBlockMatch) {
  const trackingUrl = urlBlockMatch[1];
  // Sirf percent-encoded hissa pakड़o, tracking service ka apna path suffix chhoड़ do
  const urlParamMatch = trackingUrl.match(/url=([^\/\]]+)/);
  if (urlParamMatch) {
    // Jab tak decode stable na ho jaye, baar baar decode karo (kyunki ye 2-3 baar encoded hai)
    let decoded = urlParamMatch[1];
    for (let i = 0; i < 5; i++) {
      const next = decodeURIComponent(decoded);
      if (next === decoded) break;
      decoded = next;
    }
    jobUrl = decoded;
  }
}

return {
  json: {
    title: title,
    description: description,
    budget: budget,
    skills: [],
    job_url: jobUrl,
    client_info: {
      rank: clientRank,
      payment_verified: paymentVerified,
      reviews: reviews,
      registered: registered
    }
  }
};

const jobData = $input.first().json;

// URL se unique ID nikalna (jo ~ ke baad wala hissa hai)
const idMatch = jobData.job_url.match(/~([a-zA-Z0-9]+)/);
const jobId = idMatch ? idMatch[1] : "Unknown";

return {
  json: {
    ...jobData,
    job_id: jobId
  }
};

const currentJobId = $('Extract Job ID').first().json.job_id;
const existingRows = $input.all(); // Google Sheets se aayi saari rows

// Saari existing job_ids ki list banao
const existingIds = existingRows.map(row => row.json.job_id);

// Check karo kya current job pehle se list mein hai
const isDuplicate = existingIds.includes(currentJobId);

return {
  json: {
    ...$('Extract Job ID').first().json,
    is_duplicate: isDuplicate
  }
};

